using UnityEngine;
using UnityEditor;
using System;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.stageCamera.transform.localPosition = new Vector3(4.2f, 6.2f, -5.4f);
            s.stageCamera.transform.LookAt(s.stageCamera.transform.parent.TransformPoint(new Vector3(0, 1.8f, -.8f)));
            s.stageCamera.fieldOfView = 80;
            s.OpenPage("reconstruction");
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/stage-wide-candidate.png");
            r.Log("Runtime camera review only");
        }
    }
}

